function KDGenericMultEnchantmentAmount(amt, _item, Loot, curse, primaryEnchantment) {
    amt *= 1 + ((KDGetEffLevel() - 1) / (KinkyDungeonMaxLevel - 1));
    if (Loot?.amtMult)
        amt *= Loot.amtMult;
    if (primaryEnchantment)
        amt *= 0.45;
    if (curse && KDEventHexModular[curse]?.level > 0)
        amt *= 1 + 0.5 * Math.pow(KDEventHexModular[curse].level, 0.5);
    return Math.ceil(amt);
}
function KDNormalizedMultEnchantmentAmount(amt, _item, Loot, curse, primaryEnchantment) {
    let original = amt * 0.01;
    amt *= 1 + ((KDGetEffLevel() - 1) / (KinkyDungeonMaxLevel - 1));
    if (Loot?.amtMult)
        amt *= Loot.amtMult;
    if (primaryEnchantment)
        amt *= 0.3;
    if (curse && KDEventHexModular[curse]?.level > 0)
        amt *= 1 + 0.5 * Math.pow(KDEventHexModular[curse].level, 0.5);
    return 100 * (1 - (1 - original) * Math.pow(1 - original, (amt / (100 * original))));
}
