                if (KDSoundEnabled())
                    AudioPlayInstantSoundKD(KinkyDungeonRootDirectory + "Audio/Magic.ogg");
                KDGameData.InventoryAction = "";
                KDGameData.InventoryActionContainer = [];
                KinkyDungeonLastAction = "Cast";
                KinkyDungeonAdvanceTime(1, true, true);
