        let altRoom = KDGameData.RoomType;
        let altType = altRoom ? KinkyDungeonAltFloor((mapMod && mapMod.altRoom) ? mapMod.altRoom : altRoom) : KinkyDungeonBossFloor(data.Floor);
        KDTorch(x, y - 1, altType, data.params);
