let KDSaveTimeout = 600000;
async function KinkyDungeonCompressSave(save) {
    if (window.Worker) {
        const myWorker = new Worker("out/saveworker.js");
        let pp = new Promise(function (resolve, reject) {
            myWorker.onmessage = function (e) {
                console.log('Compressed data received from worker');
                resolve(e.data);
            };
            myWorker.postMessage(save);
            console.log('Save message posted to worker');
            setTimeout(reject, KDSaveTimeout);
        });
        return Promise.resolve(pp)
            .then((v) => {
            console.log('Yay');
            myWorker.terminate();
            return v;
        })
            .catch((v) => {
            console.log('Nay');
            myWorker.terminate();
            return LZString.compressToBase64(save);
        });
    }
    else {
        console.log('Your browser doesn\'t support web workers.');
        return LZString.compressToBase64(save);
    }
}
