            KDMapData.Grid = KDMapData.Grid + KinkyDungeonOldGrid[Math.floor(X * w / KDMapData.GridWidth) + Math.floor(Y * h / KDMapData.GridHeight) * (w + 1)];
        KDMapData.Grid = KDMapData.Grid + '\n';
