    if (fromRoom != undefined && KDDoLairOutpostConnections(slot, lairid, fromRoom, fromRoomEntrance, entranceFrom))
        gen = true;
    if (KDDoLairOutpostConnections(slot, lairid, room, entrance, entranceFrom))
        gen = true;
    if (gen)
        KDBuildLairs();
