function KDDoLairOutpostConnections(slot, id, roomFrom, entranceType, entranceTypeFrom) {
    if (!KDPersonalAlt[id])
        return false;
    let ret = false;
    if (!slot.lairsToPlace) {
        slot.lairsToPlace = {};
    }
    if ((!slot.lairsToPlace[roomFrom]?.includes(id)
        && !slot.data[roomFrom]?.LairsToPlace?.includes(id)
        && !(slot.data[roomFrom]?.UsedEntrances && slot.data[roomFrom]?.UsedEntrances[id])) && roomFrom != id) {
        KDPersonalAlt[id].Entrance[roomFrom] = entranceType;
        if (slot.data[roomFrom]) {
            if (!slot.data[roomFrom].LairsToPlace) {
                slot.data[roomFrom].LairsToPlace = [];
            }
            if (!slot.data[roomFrom].LairsToPlace.includes(id))
                slot.data[roomFrom].LairsToPlace.push(id);
        }
        else {
            if (!slot.lairsToPlace[roomFrom]) {
                slot.lairsToPlace[roomFrom] = [];
            }
            if (!slot.lairsToPlace[roomFrom].includes(id))
                slot.lairsToPlace[roomFrom].push(id);
        }
        ret = true;
    }
    if (KDPersonalAlt[id].UpStairsFrom != roomFrom
        && (!slot.lairsToPlace[id]?.includes(roomFrom)
            && !slot.data[id]?.LairsToPlace?.includes(roomFrom)
            && !(slot.data[id]?.UsedEntrances && slot.data[id]?.UsedEntrances[roomFrom])) && roomFrom != id) {
        if (KDPersonalAlt[roomFrom])
            KDPersonalAlt[roomFrom].Entrance[id] = entranceTypeFrom;
        else
            KDPersonalAlt[id].EntranceTo[roomFrom] = entranceTypeFrom;
        if (slot.data[id]) {
            if (!slot.data[id].LairsToPlace) {
                slot.data[id].LairsToPlace = [];
            }
            if (!slot.data[id].LairsToPlace.includes(roomFrom))
                slot.data[id].LairsToPlace.push(roomFrom);
        }
        else {
            if (!slot.lairsToPlace[id]) {
                slot.lairsToPlace[id] = [];
            }
            if (!slot.lairsToPlace[id].includes(roomFrom))
                slot.lairsToPlace[id].push(roomFrom);
        }
        ret = true;
    }
    return ret;
}
function KDBuildLairs() {
    let data = KDMapData;
    let slot = KDGetWorldMapLocation({ x: data.mapX, y: data.mapY });
    if (slot) {
        if (!slot.lairsToPlace) {
            slot.lairsToPlace = {};
        }
        if (slot.lairsToPlace && slot.lairsToPlace[KDMapData.RoomType]?.length > 0) {
            if (!data.LairsToPlace) {
                data.LairsToPlace = [];
            }
            data.LairsToPlace.push(...slot.lairsToPlace[KDMapData.RoomType]);
            slot.lairsToPlace[KDMapData.RoomType] = undefined;
        }
    }
    let lairsToPlace = data.LairsToPlace || [];
    let lairsNotPlaced = [];
    let lairsPlaced = [];
    for (let lairName of lairsToPlace) {
        let lair = KDPersonalAlt[lairName];
        if (!lair && !KDPersonalAlt[data.RoomType]) {
            lairsNotPlaced.push(lairName);
            return;
        }
        let entrance = lair ? KDFindEntrance(lair, data) : KDFindEntranceTo(KDPersonalAlt[data.RoomType], lairName, data);
        if (entrance) {
            if (KDPlaceLairEntrance(lair, data, entrance, lairName)) {
                lairsPlaced.push(lairName);
                data.UsedEntrances[lairName] = entrance;
                let ind = data.PotentialEntrances.findIndex((ent) => {
                    return ent.x == entrance.x && ent.y == entrance.y;
                });
                if (ind >= 0)
                    data.PotentialEntrances.splice(ind, 1);
            }
            else {
                lairsNotPlaced.push(lairName);
            }
        }
        else {
            lairsNotPlaced.push(lairName);
        }
    }
    if (lairsNotPlaced.length == 0) {
        data.LairsToPlace = undefined;
    }
    else {
        data.LairsToPlace = lairsNotPlaced;
    }
}
function KDFindEntrance(lair, data) {
    let highestEntrances = [];
    let min = -1000000;
    let highestEntranceLevel = min;
    let potentialEntrances = (data.PotentialEntrances || []).filter((entrance) => {
        return lair.Entrance[data.RoomType] == entrance.Type;
    });
    for (let entrance of potentialEntrances) {
        let value = (entrance.priority || 0) + (!KDLairEntranceFilterScript[lair.Entrance[data.RoomType]] ? min
            : KDLairEntranceFilterScript[lair.Entrance[data.RoomType]](lair, data, entrance));
        if (value > highestEntranceLevel) {
            highestEntranceLevel = value;
            highestEntrances = [];
        }
        if (value >= highestEntranceLevel) {
            highestEntrances.push(entrance);
        }
    }
    if (highestEntrances.length > 0) {
        return highestEntrances[Math.floor(KDRandom() * highestEntrances.length)];
    }
    return null;
}
function KDFindEntranceTo(lairFrom, roomTo, data) {
    let highestEntrances = [];
    let min = -1000000;
    let highestEntranceLevel = min;
    let potentialEntrances = (data.PotentialEntrances || []).filter((entrance) => {
        return lairFrom.EntranceTo[roomTo] == entrance.Type;
    });
    for (let entrance of potentialEntrances) {
        let value = (entrance.priority || 0) + (!KDLairEntranceFilterScript[lairFrom.EntranceTo[roomTo]] ? min
            : KDLairEntranceFilterScript[lairFrom.EntranceTo[roomTo]](null, data, entrance, roomTo));
        if (value > highestEntranceLevel) {
            highestEntranceLevel = value;
            highestEntrances = [];
        }
        if (value >= highestEntranceLevel) {
            highestEntrances.push(entrance);
        }
    }
    if (highestEntrances.length > 0) {
        return highestEntrances[Math.floor(KDRandom() * highestEntrances.length)];
    }
    return null;
}
function KDPlaceLairEntrance(lair, data, entrance, roomTo) {
    if (KDLairEntrancePlaceScript[entrance.PlaceScript]) {
        return KDLairEntrancePlaceScript[entrance.PlaceScript](lair, data, entrance, roomTo);
    }
    return false;
}
let KDLairTypePlaceScript = {
    DragonLair: (lair, data, entrance, roomTo) => {
        return KDLairTypePlaceScript["Cave"](lair, data, entrance, roomTo);
    },
    Cave: (lair, data, entrance, roomTo) => {
        let point = { x: entrance.x, y: entrance.y };
        if ((KinkyDungeonGroundTiles + "4rY").includes(KinkyDungeonMapGet(point.x, point.y))
            && !KinkyDungeonTilesGet(point.x + ',' + point.y)?.Type) {
            KDMakeShortcutStairs(lair, point, data, roomTo);
            KinkyDungeonSkinArea({ skin: "cav" }, point.x, point.y, 1.5);
            if (!KDMapData.SpecialAreas)
                KDMapData.SpecialAreas = [];
            KDMapData.SpecialAreas.push({ x: point.x, y: point.y, radius: 2 });
            return true;
        }
        return false;
    },
    Wall: (lair, data, entrance, roomTo) => {
        let point = { x: entrance.x, y: entrance.y };
        if (("14").includes(KinkyDungeonMapGet(point.x, point.y))
            && !KinkyDungeonTilesGet(point.x + ',' + point.y)?.Type) {
            KDMakeShortcutStairs(lair, point, data, roomTo);
            if (!KDMapData.SpecialAreas)
                KDMapData.SpecialAreas = [];
            KDMapData.SpecialAreas.push({ x: point.x, y: point.y, radius: 2 });
            return true;
        }
        return false;
    },
};
let KDLairEntrancePlaceScript = {
    Cave: (lair, data, entrance, roomTo) => {
        if (entrance.Excavate?.length > 0) {
            for (let tile of entrance.Excavate) {
                if ((KinkyDungeonGroundTiles + "4").includes(KinkyDungeonMapGet(tile.x, tile.y))
                    && !KinkyDungeonTilesGet(tile.x + ',' + tile.y)?.Type) {
                    KinkyDungeonMapSet(tile.x, tile.y, 'r');
                    KDCreateEffectTile(tile.x, tile.y, {
                        name: "RubbleNoMend",
                        duration: 9999,
                    }, 0);
                }
            }
            KinkyDungeonUpdateLightGrid = true;
            KinkyDungeonGenNavMap();
        }
        return KDLairTypePlaceScript[lair?.PlaceScriptOverride || "Cave"](lair, data, entrance, roomTo);
    },
    Jail: (lair, data, entrance, roomTo) => {
        if (entrance.Excavate?.length > 0) {
            for (let tile of entrance.Excavate) {
                if ((KinkyDungeonGroundTiles + "04").includes(KinkyDungeonMapGet(tile.x, tile.y))
                    && !KinkyDungeonTilesGet(tile.x + ',' + tile.y)?.Type) {
                    KinkyDungeonMapSet(tile.x, tile.y, '2');
                }
            }
            KinkyDungeonUpdateLightGrid = true;
            KinkyDungeonGenNavMap();
        }
        return KDLairTypePlaceScript[lair?.PlaceScriptOverride || "Wall"](lair, data, entrance, roomTo);
    },
};
function KDGenHighSecCondition(force, enemy) {
    if (((force || KinkyDungeonFlags.has("LeashToPrison"))
        && !(KinkyDungeonAltFloor(KDGameData.RoomType)?.isPrison))
        || (KDSelfishLeash(enemy))) {
        let altType = KDGetAltType(MiniGameKinkyDungeonLevel);
        let slot = KDGetWorldMapLocation(KDCoordToPoint(KDGetCurrentLocation()));
        return (!altType || altType.placeJailEntrances || slot?.main == KDGameData.RoomType);
    }
    return false;
}
let KDLairEntranceFilterScript = {
    Cave: (lair, data, entrance, roomTo) => {
        let nearestDist = KinkyDungeonGetClosestSpecialAreaDist(entrance.x, entrance.y);
        if (nearestDist < 3)
            return -1000;
        return 1;
    },
    Jail: (lair, data, entrance, roomTo) => {
        let nearestDist = KinkyDungeonGetClosestSpecialAreaDist(entrance.x, entrance.y);
        if (nearestDist < 3)
            return -1000;
        let nearestJail = KinkyDungeonNearestJailPoint(entrance.x, entrance.y, ["jail"]);
        if (nearestJail) {
            return KDistChebyshev(nearestJail.x - entrance.x, nearestJail.y - entrance.y);
        }
        return -1000;
    },
};
function KDMakeShortcutStairs(lair, point, data, roomTo) {
    KinkyDungeonMapSet(point.x, point.y, 'H');
    let tile = KinkyDungeonTilesGet(point.x + ',' + point.y) || {};
    let slot = KDGetWorldMapLocation({ x: data.mapX, y: data.mapY });
    let faction = lair?.OwnerFaction || "";
    if (slot) {
        let jx = slot.jx || 0;
        let jy = slot.jy || slot.y;
        let journeySlot = KDGameData.JourneyMap[jx + ',' + jy];
        if (journeySlot) {
            if (!lair)
                faction = journeySlot.Faction;
            if (!journeySlot.SideRooms.includes(lair ? lair.Name : roomTo))
                journeySlot.SideRooms.push(lair ? lair.Name : roomTo);
            if (!journeySlot.HiddenRooms) {
                journeySlot.HiddenRooms = {};
            }
            if (lair?.Hidden)
                journeySlot.HiddenRooms[lair.Name] = true;
        }
        tile.ShortcutIndex = roomTo != undefined ? roomTo : data.ShortcutPositions.length;
        if (data.ShortcutPositions.includes) {
            let newObj = {};
            for (let i = 0; i < Object.values(data.ShortcutPositions).length; i++) {
                newObj[i] = data.ShortcutPositions[i];
            }
            data.ShortcutPositions = newObj;
        }
        data.ShortcutPositions[tile.ShortcutIndex] = point;
    }
    else {
        return false;
    }
    tile.MapMod = "None";
    tile.Faction = faction;
    tile.EscapeMethod = "None";
    tile.RoomType = lair ? lair.Name : roomTo;
    KinkyDungeonTilesSet(point.x + ',' + point.y, tile);
    KinkyDungeonMapSet(point.x, point.y, 'H');
    KDRemoveAoEEffectTiles(point.x, point.y, [], 0.5);
}
function KDGetRegiments(location, Room) {
    if (!KDGameData.Regiments)
        KDGameData.Regiments = {};
    if (!location) {
        return Object.values(KDGameData.Regiments);
    }
}
function UpdateRegiments(coords) {
    let loc = KDGetWorldMapLocation({ x: coords.mapX, y: coords.mapY });
    if (!loc)
        return;
    let Map = loc.data[coords.room];
    Map.Regiments = {};
    for (let reg of KDGetRegiments()) {
        if (KDCompareLocation(reg.location, coords)) {
            Map.Regiments[reg.id] = reg.id;
        }
    }
}
let KDMapTickTime = 50;
let KDMapTickRange = 2;
function KDTickMaps(delta, minFloor, maxFloor, onlyMain, updateReg, updateChests) {
    if (MiniGameKinkyDungeonLevel >= minFloor && MiniGameKinkyDungeonLevel <= maxFloor) {
        KDUpdateRepopQueue(KDMapData, delta);
    }
    if (KinkyDungeonFlags.get("KDMapTick"))
        return false;
    KinkyDungeonSetFlag("KDMapTick", KDMapTickTime);
    let mapsToUpdate = [];
    let mapsWithUpdateNPCs = [];
    for (let y = minFloor; y <= maxFloor; y++) {
        let mapSlot = KDWorldMap[0 + ',' + y];
        if (mapSlot) {
            for (let data of Object.values(mapSlot.data)) {
                mapsToUpdate.push({
                    mapX: 0,
                    mapY: y,
                    room: data.RoomType,
                });
            }
        }
    }
    for (let y = 0; y <= KDGameData.HighestLevelCurrent; y++) {
        let mapSlot = KDWorldMap[0 + ',' + y];
        if (mapSlot) {
            let visitedRooms = {};
            for (let data of Object.values(mapSlot.data)) {
                if (KDGetPersistentNPCCache({
                    mapX: 0,
                    mapY: y,
                    room: data.RoomType,
                })?.length > 0) {
                    mapsWithUpdateNPCs.push({
                        mapX: 0,
                        mapY: y,
                        room: data.RoomType,
                    });
                    visitedRooms[data.RoomType] = true;
                }
            }
            let journeySlot = KDGameData.JourneyMap[(mapSlot.jx != undefined ? mapSlot.jx : 0) + ',' + (mapSlot.jy != undefined ? mapSlot.jy : y)];
            if (journeySlot?.SideRooms) {
                for (let r of journeySlot.SideRooms) {
                    if (KDSideRooms[r]?.altRoom && !visitedRooms[KDSideRooms[r].altRoom]) {
                        if (KDGetPersistentNPCCache({
                            mapX: 0,
                            mapY: y,
                            room: KDSideRooms[r].altRoom,
                        })?.length > 0) {
                            mapsWithUpdateNPCs.push({
                                mapX: 0,
                                mapY: y,
                                room: KDSideRooms[r].altRoom,
                            });
                            visitedRooms[KDSideRooms[r].altRoom] = true;
                        }
                    }
                }
            }
        }
    }
    for (let coords of mapsToUpdate) {
        let loc = KDGetWorldMapLocation({ x: coords.mapX, y: coords.mapY });
        if (!loc)
            continue;
        let data = loc.data[coords.room];
        if (data != KDMapData) {
            KDUpdateRepopQueue(data, KDMapTickTime);
        }
        if (updateReg)
            UpdateRegiments(coords);
        if (updateChests)
            KDRefillChests(data);
    }
    for (let coords of mapsWithUpdateNPCs) {
        let loc = KDGetWorldMapLocation({ x: coords.mapX, y: coords.mapY });
        if (!loc)
            continue;
        let data = loc.data[coords.room];
        if (data) {
        }
        KDSpawnPersistentNPCs(coords, data == KDMapData);
        KDWanderPersistentNPCs(coords, data == KDMapData);
        KDRunPersistentNPCScripts(coords, data == KDMapData);
    }
    return true;
}
let KDRefillChestInterval = 200;
let KDRefillChestChance = 0.5;
function KDRefillChests(data) {
    if (!data.data)
        data.data = {};
    let lastRefill = data.data.lastChestRefill;
    let currentTick = KinkyDungeonCurrentTick;
    if (KDGameData.PrisonerState == 'jail') {
        if (lastRefill + KDRefillChestInterval < currentTick) {
            lastRefill = currentTick;
            for (let x = 0; x < data.GridWidth; x++) {
                for (let y = 0; y < data.GridHeight; y++) {
                    if (data.Tiles[x + ',' + y]?.refill) {
                        KDRefillTick(x, y, data);
                    }
                }
            }
        }
    }
}
function KDRefillTick(x, y, data) {
    let tile = data.Tiles[x + ',' + y];
    if (tile) {
        let type = tile.Type;
        if (KDRefillTypes[type]) {
            KDRefillTypes[type](x, y, tile, data);
        }
    }
}
let KDRefillTypes = {
    Chest: (x, y, tile, data) => {
        let empty = KinkyDungeonMapDataGet(data, x, y) == 'c';
        if (empty
            && (data != KDMapData
                || KDistChebyshev(x - KDPlayer().x, y - KDPlayer().y) > Math.max(GiantMapOptimizations || 0, 10))
            && KDRandom() < KDRefillChestChance) {
            let refillTo = tile.origloot;
            if (refillTo) {
                KinkyDungeonMapDataSet(data, x, y, 'C');
                tile.Loot = refillTo;
                tile.Roll = KDRandom();
                tile.Lock = "White";
            }
        }
    }
};
