        kdminimap.lineStyle(4, 0);
        kdminimap.beginFill(0xfffafa, 1.);
        kdminimap.drawCircle(w / 2 * scale + scale / 2 + (KinkyDungeonPlayerEntity.x - KDInspectCamera.x) * scale, h / 2 * scale + scale / 2 + (KinkyDungeonPlayerEntity.y - KDInspectCamera.y) * scale, scale);
        kdminimap.endFill();
        if (KinkyDungeonInspect) {
            let xpre = w / 2 * scale - scale * KinkyDungeonGridWidthDisplay + scale * (KDInspectCamera.x - KinkyDungeonPlayerEntity.x);
            let ypre = h / 2 * scale - scale * KinkyDungeonGridHeightDisplay + scale * (KDInspectCamera.y - KinkyDungeonPlayerEntity.y);
            let xx = Math.max(0, xpre);
            let yy = Math.max(0, ypre);
            kdminimap.lineStyle(2, 0xfffafa);
            kdminimap.drawRect(xx, yy, Math.min(scale * w - xx, 2 * scale * KinkyDungeonGridWidthDisplay + Math.min(0, xpre)), Math.min(scale * h - yy, 2 * scale * KinkyDungeonGridHeightDisplay + Math.min(0, ypre)));
            kdminimap.endFill();
        }
