function KDGetNearestInterestingLabel(x, y, entity, ignoreID, ignoreEntity, typeFilter = "", maxDist = 1000, _navigable = true) {
    if (!KDMapData.Labels)
        return null;
    let filtered = [];
    if (typeFilter) {
        if (!KDMapData.Labels[typeFilter])
            return null;
        for (let l of KDMapData.Labels[typeFilter]) {
            if (l.interesting &&
                KDPointWanderable(l.x, l.y) &&
                (l.faction && entity && l.faction == KDGetFaction(entity)) && (ignoreEntity
                || (ignoreID && KinkyDungeonNoEnemyExceptID(l.x, l.y, true, ignoreID))
                || (!ignoreID && KinkyDungeonNoEnemy(l.x, l.y, true)))) {
                filtered.push(l);
            }
        }
    }
    else {
        for (let t of Object.values(KDMapData.Labels)) {
            for (let l of t) {
                if (l.interesting &&
                    KDPointWanderable(l.x, l.y) &&
                    (l.faction && entity && l.faction == KDGetFaction(entity)) && (ignoreEntity
                    || (ignoreID && KinkyDungeonNoEnemyExceptID(l.x, l.y, true, ignoreID))
                    || (!ignoreID && KinkyDungeonNoEnemy(l.x, l.y, true)))) {
                    filtered.push(l);
                }
            }
        }
    }
    let dist = maxDist;
    let label = null;
    let dd = dist;
    for (let l of filtered) {
        if (KDistChebyshev(l.x - x, l.y - y) > dist)
            continue;
        dd = KDistEuclidean(l.x - x, l.y - y);
        if (dd < dist) {
            dist = dd;
            label = l;
        }
    }
    return label;
}
