function KDRunDefeatForEnemy() {
    let CD = KDCustomDefeat;
    let CDE = KDCustomDefeatEnemy;
    KDCustomDefeat = "";
    KDCustomDefeatEnemy = null;
    if (CD && KDCustomDefeats[CD])
        KDCustomDefeats[CD](CDE);
    else if (!KinkyDungeonFlags.get("CustomDefeat")) {
        if (KDRunRegularJailDefeatAttempt(CDE)) {
            let putInJail = KinkyDungeonFlags.has("LeashToPrison");
            if (CDE?.IntentLeashPoint) {
                let exit = KDGetNearestExit(CDE.x, CDE.y, KDMapData, true);
                if (exit && (exit.x != CDE.IntentLeashPoint.x || exit.y != CDE.IntentLeashPoint.y))
                    putInJail = false;
            }
            KinkyDungeonDefeat(putInJail, CDE);
        }
    }
}
function KDRunRegularJailDefeatAttempt(CDE, allowMain = true, runBackup = true) {
    let forceFaction = KDGetLeashFaction(CDE);
    let jailroom = KDGetLeashJailRoom(CDE);
    let slot = KDGetWorldMapLocation(KDCurrentWorldSlot);
    let altType = KDGetAltType(MiniGameKinkyDungeonLevel);
    let fromHere = false;
    if (!((slot?.main || "") == KDGameData.RoomType)
        && (!altType || (altType.placeJailEntrances
            && (!altType.sameFactionJailOnly || forceFaction == KDGetMainFaction())
            && (!altType.friendlyFactionOnly || KDFactionFavorable(KDGetMainFaction(), forceFaction))) || slot?.main == KDGameData.RoomType)
        && !KDSelfishLeash(CDE))
        fromHere = true;
    let outpost = KDAddOutpost(slot, fromHere ? KDGameData.RoomType : slot.main || "", jailroom, forceFaction || "Jail", KDLairTypes[jailroom || "Jail"]?.AlwaysHide, "Jail", fromHere ? slot.main || "" : undefined, fromHere ? "Jail" : undefined, fromHere ? "Jail" : undefined, true);
    if (KDMapData.RoomType == outpost)
        return true;
    if (KDHasEntranceToJailRoom(outpost || jailroom, KDGetCurrentLocation(), allowMain)) {
        return true;
    }
    if (!runBackup)
        return false;
    let exit = KDGetNearestExit(CDE.x, CDE.y, KDMapData, true);
    let oldLeash = KDPlayer().leash;
    if (!CDE.homeCoord) {
        CDE.homeCoord = KDGetCurrentLocation();
    }
    let currentMapData = KDMapData;
    KDGoThruTile(exit.x, exit.y, true, true, false);
    let entrance = KDGetNearestExitTo(currentMapData.RoomType, currentMapData.mapX, currentMapData.mapY, 1, 1, KDMapData, true);
    let altRoom = KDGetAltType(MiniGameKinkyDungeonLevel);
    if (!entrance || (altRoom?.nostartstairs && entrance.x == KDMapData.StartPosition.x
        && entrance.y == KDMapData.StartPosition.y)) {
        entrance = KDMapData.EndPosition;
    }
    KDMovePlayer(entrance.x, entrance.y, false);
    KDDespawnEnemy(CDE, undefined, currentMapData, KDMapData.RoomType);
    let nextExit = KDGetNearestExitTo(currentMapData.RoomType, currentMapData.mapX, currentMapData.mapY, CDE.x, CDE.y, KDMapData, true);
    if (nextExit) {
        CDE.despawnX = nextExit.x;
        CDE.despawnY = nextExit.y;
    }
    else {
        CDE.despawnX = KDMapData.EndPosition.x;
        CDE.despawnY = KDMapData.EndPosition.y;
    }
    KDPlayer().leash = oldLeash;
    if (CDE)
        KDGameData.JailGuard = CDE.id;
    if (CDE && KinkyDungeonJailGuard()) {
        KDAttachLeashOrCollar(KinkyDungeonJailGuard(), KDPlayer(), 1, true);
        if (!KDPlayer().leash)
            KinkyDungeonAttachTetherToEntity(2.5, KinkyDungeonJailGuard(), KDPlayer());
        else {
            KDPlayer().leash.x = CDE.x;
            KDPlayer().leash.y = CDE.y;
        }
        let guard = KinkyDungeonJailGuard();
        guard.aware = true;
        guard.gx = guard.x;
        guard.gy = guard.y;
        let action = "CaptureJail";
        if (guard.IntentAction != action) {
            KDIntentEvents[action].trigger(guard, {});
        }
        KDAssignLeashPoint(CDE);
        if (!CDE.IntentLeashPoint) {
            CDE.gx = AIData.nearestJail.x;
            CDE.gy = AIData.nearestJail.y;
        }
    }
    let en = KinkyDungeonEntityAt(entrance.x, entrance.y);
    if (en) {
        let pp = KinkyDungeonGetNearbyPoint(en.x, en.y, true);
        if (pp) {
            KDMoveEntity(en, pp.x, pp.y, true, false, false, false, true);
        }
    }
    return false;
}
let KDCustomDefeat = "";
let KDCustomDefeatEnemy = null;
function KDMakeHostile(enemy, timer) {
    if (!timer)
        timer = KDMaxAlertTimerAggro;
    if (!enemy.hostile)
        enemy.hostile = timer;
    else
        enemy.hostile = Math.max(enemy.hostile, timer);
    delete enemy.ceasefire;
    delete enemy.allied;
}
function KDCheckVulnerableBackstab(enemy) {
    if (KinkyDungeonAggressive(enemy) && enemy != KinkyDungeonLeashingEnemy()) {
        if (KDistChebyshev(enemy.fx - enemy.x, enemy.fy - enemy.y) < 1.5 && !enemy.Enemy.tags.noflank) {
            if (enemy.fx && enemy.fx) {
                if (enemy.x * 2 - enemy.fx == KinkyDungeonPlayerEntity.x && enemy.y * 2 - enemy.fy == KinkyDungeonPlayerEntity.y) {
                    KDAddThought(enemy.id, "Annoyed", 4, 1);
                    enemy.vulnerable = Math.max(enemy.vulnerable, 1);
                    if (!KinkyDungeonFlags.get("tut_nothingpersonnel")) {
                        KinkyDungeonSetFlag("tut_nothingpersonnel", -1);
                        KinkyDungeonSendTextMessage(10, TextGet("KDTut_TeleCrit"), KDTutorialColor, 10);
                    }
                    return true;
                }
            }
            else if (!enemy.fx && !enemy.fy) {
                let xmod = 0;
                if (!enemy.Enemy?.nonDirectional) {
                    xmod = enemy.flip ? 1 : -1;
                }
                if (enemy.x + xmod == KinkyDungeonPlayerEntity.x && enemy.y == KinkyDungeonPlayerEntity.y) {
                    KDAddThought(enemy.id, "Confused", 4, 1);
                    enemy.vulnerable = Math.max(enemy.vulnerable, 1);
                    return true;
                }
            }
        }
    }
    return false;
}
function KDGetAI(enemy) {
    if (enemy.AI)
        return enemy.AI;
    else
        return enemy.Enemy.AI;
}
let KDThoughtBubbles = new Map();
function KDAddThought(id, name, priority, duration) {
    let pri = -1;
    let n = "";
    let i = 0;
    let d = 1;
    if (KDThoughtBubbles.has(id)) {
        pri = KDThoughtBubbles.get(id).priority;
        n = KDThoughtBubbles.get(id).name;
        d = KDThoughtBubbles.get(id).duration;
        i = KDThoughtBubbles.get(id).index;
    }
    if (priority > pri || (n != name && KinkyDungeonCurrentTick > d + i) || (n != name && priority >= pri)) {
        KDThoughtBubbles.set(id, {
            name: name,
            priority: priority,
            duration: duration,
            index: KinkyDungeonCurrentTick,
        });
    }
}
function KDGetEnemyPlayLine(enemy) {
    return enemy.playLine || enemy.Enemy.playLine || "";
}
function KDEnemyCanTalk(enemy) {
    return enemy?.Enemy && !enemy.Enemy.tags?.gagged && (enemy.Enemy.tags.jailer || enemy.Enemy.tags.jail || KDGetEnemyPlayLine(enemy)) && !(enemy.silence > 0);
}
let AIData = {};
