function KDEnemyAccuracy(enemy, player) {
    let accuracy = enemy.Enemy.accuracy ? enemy.Enemy.accuracy : 1.0;
    if (enemy.distraction)
        accuracy = accuracy / (1 + 1.5 * enemy.distraction / enemy.Enemy.maxhp);
    if (enemy.boundLevel)
        accuracy = accuracy / (1 + 0.5 * enemy.boundLevel / enemy.Enemy.maxhp);
    if (enemy.blind > 0)
        accuracy = KDistChebyshev(enemy.x - player.x, enemy.y - player.y) > 1.5 ? 0 : accuracy * 0.5;
    if (player?.player) {
        if (accuracy < 1 && KDistChebyshev(enemy.x - player.x, enemy.y - player.y) < 1.5) {
            let penalty = KDPlayerEvasionPenalty();
            if (penalty > 0) {
                if (!KinkyDungeonStatsChoice.get("tut_AccuracyClose")) {
                    KinkyDungeonStatsChoice.set("tut_AccuracyClose", true);
                    KinkyDungeonSendTextMessage(10, TextGet("tut_AccuracyClose2"), KDBaseWhite, 5);
                    KinkyDungeonSendTextMessage(10, TextGet("tut_AccuracyClose1"), KDBaseWhite, 5);
                }
            }
            accuracy += penalty;
        }
    }
    else if (player?.Enemy) {
        if (player.bind > 0)
            accuracy *= 3;
        else if (player.slow > 0)
            accuracy *= 2;
        if ((player.stun > 0 || player.freeze > 0))
            accuracy *= 5;
        else {
            if (player.distraction > 0)
                accuracy *= 1 + 2 * Math.min(1, player.distraction / player.Enemy.maxhp);
            if (player)
                accuracy *= 1 + 0.25 * KDBoundEffects(player);
        }
        if (player.vulnerable)
            accuracy *= KDVulnerableHitMult;
    }
    accuracy *= KinkyDungeonMultiplicativeStat(-KDEntityBuffedStat(enemy, "Accuracy"));
    accuracy *= KinkyDungeonMultiplicativeStat(KDEntityBuffedStat(enemy, "AccuracyPenalty"));
    return Math.min(1, accuracy);
}
