        let data = {
            item: item,
            target: target,
            restraint: r,
            type: KDRestraintBondageType(item),
            override: undefined,
            overridePriority: 0,
            mult: r.npcBondageMult || 2,
        };
        if (r.quickBindMult && target && !KinkyDungeonIsDisabled(target)) {
            data.mult *= r.quickBindMult;
            data['quickBind'] = true;
        }
        KinkyDungeonSendEvent("calcBondageMult", data);
