function KDDrawMinimap(MinimapX, MinimapY) {
    if (kdminimap.visible) {
        let zIndex = (KDExpandMinimap || MouseIn(MinimapX, MinimapY, KDMinimapWidth() + 21, KDMinimapHeight() + 21)) ? 150 : 90;
        if (KDExpandMinimap) {
            KDDrawMMButtons(MinimapX, MinimapY, zIndex);
            KDDrawRightMMButtons(MinimapX, MinimapY, zIndex, KDMinimapWidth() + 21);
        }
        kdminimap.zIndex = zIndex - 1;
        DrawButtonKDEx("minimapdummy", (_bdata) => {
            KDExpandMinimap = !KDExpandMinimap;
            return true;
        }, true, MinimapX - 10, MinimapY - 10, KDMinimapWidth() + 21, KDMinimapHeight() + 21, "", KDButtonColor, undefined, undefined, false, true, KDBaseBlack, undefined, undefined, { zIndex: zIndex - 2, alpha: 0., hotkey: KDHotkeyToText(KinkyDungeonKeyMap[0]), hotkeyPress: KinkyDungeonKeyMap[0] });
        if (KDMinimapWCurrent != KDMinimapWTarget || KDMinimapHCurrent != KDMinimapHTarget) {
            KDRedrawMM = 2;
        }
        KDMinimapWCurrent = (KDMinimapWTarget + KDUISmoothness * KDMinimapWCurrent) / (1 + KDUISmoothness);
        KDMinimapHCurrent = (KDMinimapHTarget + KDUISmoothness * KDMinimapHCurrent) / (1 + KDUISmoothness);
        if (Math.abs(KDMinimapWCurrent - KDMinimapWTarget) < 5)
            KDMinimapWCurrent = KDMinimapWTarget;
        if (Math.abs(KDMinimapHCurrent - KDMinimapHTarget) < 5)
            KDMinimapHCurrent = KDMinimapHTarget;
        let escapeMethod = KDGetEscapeMethod(MiniGameKinkyDungeonLevel);
        let escape = KDCanEscape(escapeMethod);
        let escapeText = KDGetEscapeMinimapText(escapeMethod)?.split('|');
        if (escapeText) {
            let spacing = 17;
            let II = -(escapeText.length - 1);
            for (let s of escapeText) {
                DrawTextFitKD(s, kdminimap.x + KDMinimapWCurrent / 2, kdminimap.y + KDMinimapHCurrent - 12 + II++ * spacing, 0.75 * KDMinimapWCurrent, escape ? KDBaseMint : KDBaseRed, KDTextGray0, 16, "center", zIndex + 1);
            }
        }
    }
    kdminimap.x = MinimapX;
    kdminimap.y = MinimapY;
}
