        bullet: bullet,
        channel: predata.channel,
        slow: predata.slow,
        targetX: Enemy.x,
        targetY: Enemy.y,
        enemy: Enemy,
        miss: !evaded,
        disarm: disarm,
        damage: Damage,
        vulnConsumed: predata.vulnConsumed,
