function KinkyDungeonLoadSpellsConfig() {
    let spellsChoice = localStorage.getItem('KinkyDungeonSpellsChoice' + KinkyDungeonSpellsConfig);
    let spellsChoiceToggle = localStorage.getItem('KDSpellsChoiceToggle' + KinkyDungeonSpellsConfig);
    if (spellsChoice) {
        KDClearChoices();
        let list = JSON.parse(spellsChoice);
        let i = 0;
        for (let spell of list) {
            if (spellsChoiceToggle && spellsChoiceToggle[i]) {
                KinkyDungeonSpellChoicesToggle[i] = true;
            }
            if (KDHasSpell(spell)) {
                KinkyDungeonSpellChoices[i] = KinkyDungeonSpells.findIndex((sp) => {
                    return sp.name == spell;
                });
            }
            else if (KinkyDungeonInventoryGetConsumable(spell)) {
                KinkyDungeonConsumableChoices[i] = spell;
            }
            else if (KinkyDungeonInventoryGetWeapon(spell)) {
                KinkyDungeonWeaponChoices[i] = spell;
            }
            else if (KinkyDungeonInventoryGet(spell)) {
                KinkyDungeonArmorChoices[i] = spell;
            }
            i++;
        }
    }
}
function KinkyDungeonSaveSpellsConfig() {
    let list = KinkyDungeonSpellChoices.map((index) => { return KinkyDungeonSpells[index]?.name; });
    for (let i = 0; i < KinkyDungeonSpellChoiceCount; i++) {
        if (KinkyDungeonConsumableChoices[i])
            list[i] = KinkyDungeonConsumableChoices[i];
        else if (KinkyDungeonWeaponChoices[i])
            list[i] = KinkyDungeonWeaponChoices[i];
        else if (KinkyDungeonArmorChoices[i])
            list[i] = KinkyDungeonArmorChoices[i];
    }
    let list2 = KinkyDungeonSpellChoicesToggle.map((index) => { return index ? 1 : 0; });
    localStorage.setItem('KinkyDungeonSpellsChoice' + KinkyDungeonSpellsConfig, JSON.stringify(list));
    localStorage.setItem('KDSpellsChoiceToggle' + KinkyDungeonSpellsConfig, JSON.stringify(list2));
}
