function KDGetGhostThresh() {
    let amt = 3;
    let rep = KinkyDungeonGoddessRep.Ghost;
    if (rep > -25)
        amt -= 1;
    if (rep > 0)
        amt -= 1;
    if (rep > 40)
        amt -= 1;
    return Math.max(amt, 0);
}
