                        filters[f[0]].red = GetPalette(C, faction)[f[1].color].red;
                        filters[f[0]].blue = GetPalette(C, faction)[f[1].color].blue;
                        filters[f[0]].green = GetPalette(C, faction)[f[1].color].green;
