function KinkyDungeonQuickGrid(I, Width, Height, Xcount) {
    let i = 0;
    let h = 0;
    let v = 0;
    while (i < I) {
        if (h < Xcount - 1)
            h++;
        else {
            h = 0;
            v++;
        }
        i++;
    }
    return { x: Width * h, y: Height * v };
}
