function KDSlimeImmuneEntity(entity) {
    if (entity.player) {
        if (KinkyDungeonGetBuffedStat(KinkyDungeonPlayerBuffs, "glueDamageResist") >= 0.45)
            return true;
        for (let inv of KinkyDungeonAllRestraint()) {
            if (KDRestraint(inv).slimeWalk) {
                return true;
            }
        }
    }
    else
        return KDSlimeImmune(entity);
}
function KDSoapImmuneEntity(entity) {
    if (entity.player) {
        if (KinkyDungeonGetBuffedStat(KinkyDungeonPlayerBuffs, "soapDamageResist") >= 0.45)
            return true;
        for (let inv of KinkyDungeonAllRestraint()) {
            if (KDRestraint(inv).soapWalk) {
                return true;
            }
        }
    }
    else
        return KDSoapImmune(entity);
}
function KDSlimeWalker(entity) {
    if (KDSlimeImmuneEntity(entity))
        return true;
    else if (!entity.player && KDIsFlying(entity))
        return true;
    return false;
}
function KDSoapWalker(entity) {
    if (KDSoapImmuneEntity(entity))
        return true;
    else if (!entity.player && KDIsFlying(entity))
        return true;
    return false;
}
function KDSlimeImmune(enemy) {
    return enemy.Enemy?.tags.slime
        || KinkyDungeonGetImmunity(enemy.Enemy?.tags, enemy.Enemy?.Resistance?.profile, "glue", "immune")
        || enemy.Enemy?.tags.slimewalk
        || KDEntityBuffedStat(enemy, "glueDamageResist") >= 0.45;
}
function KDSoapImmune(enemy) {
    return enemy.Enemy?.tags.slime
        || KinkyDungeonGetImmunity(enemy.Enemy?.tags, enemy.Enemy?.Resistance?.profile, "soap", "immune")
        || enemy.Enemy?.tags.soapwalk
        || KDEntityBuffedStat(enemy, "soapDamageResist") >= 0.45;
}
