                let point = KinkyDungeonGetRandomEnemyPoint(true, false, undefined, 10, 10);
                if (point) {
                    let ee = DialogueCreateEnemy(point.x, point.y, enemy.Enemy.name);
                    ee.faction = enemy.faction;
                }
