                if (KDEnemyHasFlag(enemy, "killtarget") && KinkyDungeonVisionGet(enemy.x, enemy.y) > 0) {
                    KDDraw(kdenemystatusboard, kdpixisprites, enemy.id + "_killtarg", KinkyDungeonRootDirectory + "UI/QuestTarget.png", (enemy.visual_x - data.CamX) * KinkyDungeonGridSizeDisplay, (enemy.visual_y - data.CamY) * KinkyDungeonGridSizeDisplay, KinkyDungeonSpriteSize, KinkyDungeonSpriteSize, undefined, {
                        zIndex: -5,
                        tint: 0xE30022,
                    });
                }
