function KDEnemyHelpfulness(enemy) {
    let mult = KDIsInPartyID(enemy.id) ? 1.5 : 1.0;
    if (!enemy.personality)
        return 1.0;
    if (KDStrictPersonalities.includes(enemy.personality))
        return mult * 0.33;
    if (KDLoosePersonalities.includes(enemy.personality))
        return mult * 1.75;
    return mult * 1.0;
}
