function KDDefaultPrereqs(enemy, AIData, dist, maxdist, chance, restraintTags, force, Lock = "Red") {
    return dist < maxdist
        && (!AIData.domMe || force)
        && !KDEnemyHasFlag(enemy, "playstart")
        && (!KinkyDungeonFlags.get("DangerFlag") || force)
        && (!KinkyDungeonFlags.get("BondageOffer") || force)
        && !KinkyDungeonFlags.get("NoTalk")
        && (KinkyDungeonStatsChoice.get("Undeniable") || KDRandom() < chance || force)
        && (!restraintTags || KinkyDungeonGetRestraint({ tags: restraintTags }, KDGetEffLevel() * 1.5 + KDGetOfferLevelMod(), KDCurrIndex(), undefined, Lock, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, undefined, {
            allowLowPower: true
        }) != undefined)
        && (KinkyDungeonStatsChoice.get("Undeniable") || !KDIsBrat(enemy) || force);
}
function KDShopTrigger(name) {
    return {
        dialogue: name,
        allowedPrisonStates: ["parole", ""],
        nonHostile: true,
        noCombat: true,
        talk: true,
        excludeTags: ["noshop"],
        blockDuringPlaytime: true,
        prerequisite: (enemy, dist, _AIData) => {
            return (dist < 1.5
                && !KinkyDungeonFlags.get("NoTalk")
                && !KDGameData.NoForceGreet
                && !(KDGameData.SleepTurns > 0)
                && KDEnemyHasFlag(enemy, name)
                && !KDEnemyHasFlag(enemy, "NoShop"));
        },
        weight: (_enemy, _dist) => {
            return 100;
        },
    };
}
function KDRecruitTrigger(name, dialogue) {
    if (dialogue)
        return {
            dialogue: name,
            allowedPrisonStates: ["parole", "", "chase"],
            requireTags: dialogue.tags,
            requireTagsSingle: dialogue.singletag,
            excludeTags: dialogue.excludeTags,
            playRequired: true,
            nonHostile: true,
            noCombat: true,
            blockDuringPlaytime: true,
            prerequisite: (enemy, dist, _AIData) => {
                return (dist < 1.5
                    && !KDGameData.RecruitedFaction
                    && !KinkyDungeonFlags.get("DangerFlag")
                    && !KinkyDungeonFlags.get(name)
                    && !KinkyDungeonFlags.get("NoTalk")
                    && KinkyDungeonCurrentDress != dialogue.outfit
                    && !enemy.faction
                    && !enemy.allied
                    && KDFactionRelation("Player", KDGetFactionOriginal(enemy)) > -0.1
                    && KDRandom() < dialogue.chance);
            },
            weight: (_enemy, _dist) => {
                return 10;
            },
        };
    return null;
}
function KDBossTrigger(name, enemyName) {
    return {
        dialogue: name,
        nonHostile: true,
        prerequisite: (enemy, dist, _AIData) => {
            return (dist < 2.5
                && KDGetFaction(enemy) != "Player"
                && !KinkyDungeonFlags.get("NoTalk")
                && !(KDGameData.SleepTurns > 0)
                && enemyName.includes(enemy.Enemy.name)
                && !KinkyDungeonFlags.has("BossUnlocked")
                && !KinkyDungeonFlags.has("BossDialogue" + name));
        },
        weight: (_enemy, _dist) => {
            return 100;
        },
    };
}
function KDBossLose(name, enemyName, tags, condition) {
    return {
        dialogue: name,
        prerequisite: (enemy, dist, _AIData) => {
            return (dist < 1.5
                && !KinkyDungeonFlags.get("NoTalk")
                && KDGetFaction(enemy) != "Player"
                && !(KDGameData.SleepTurns > 0)
                && enemyName.includes(enemy.Enemy.name)
                && !KinkyDungeonFlags.has("BossUnlocked")
                && ((!condition && !KinkyDungeonHasWill(0.1)) || (condition && condition()))
                && (!tags || !KinkyDungeonGetRestraint({ tags: tags }, MiniGameKinkyDungeonLevel * 2, KDCurrIndex())));
        },
        weight: (_enemy, _dist) => {
            return 100;
        },
    };
}
function KinkyDungeonGetShopForEnemy(enemy, guaranteed) {
    if (enemy.Enemy.tags.noshop)
        return "";
    let shoplist = [];
    for (let s of Object.values(KDShops)) {
        let end = false;
        if (s.tags) {
            for (let t of s.tags) {
                if (!enemy.Enemy.tags[t]) {
                    end = true;
                    break;
                }
            }
        }
        let hasTag = !s.singletag;
        if (!end && s.singletag) {
            for (let t of s.singletag) {
                if (enemy.Enemy.tags[t]) {
                    hasTag = true;
                    break;
                }
            }
        }
        if (!hasTag)
            end = true;
        if (!end && (guaranteed || !s.chance || KDRandom() < s.chance))
            shoplist.push(s.name);
    }
    if (shoplist.length > 0)
        return shoplist[Math.floor(KDRandom() * shoplist.length)];
    return "";
}
