    "MummyElevator": {
        response: "Default",
        clickFunction: (_gagged, _player) => {
            let e = KDGetSpeaker();
            if (e) {
                e.hp = 0;
                let en = DialogueCreateEnemy(e.x, e.y, KDGetEffLevel() > 4 ? "ClericHigh" : "Mummy");
                en.hostile = 9999;
                en.faction = "Enemy";
                en.aware = true;
                KDRunCreationScript(en, KDGetCurrentLocation());
                if (KDGameData.RoomType == "ElevatorEgyptian") {
                    en = DialogueCreateEnemy(e.x, e.y + 11, "SarcoKraken");
                    en.faction = "Enemy";
                    en.maxlifetime = 9999;
                    en.lifetime = 9999;
                    if (KinkyDungeonTilesGet((e.x) + ',' + (e.y + 11))) {
                        KinkyDungeonTilesGet((e.x) + ',' + (e.y + 11)).Skin = "SarcophagusGone";
                    }
                    KDRunCreationScript(en, KDGetCurrentLocation());
                }
                else if (KDGameData.RoomType == "ElevatorEgyptian2") {
                    for (let X = 1; X < KDMapData.GridWidth - 1; X++) {
                        for (let Y = 1; Y < KDMapData.GridHeight - 1; Y++) {
                            if (KinkyDungeonMapGet(X, Y) == 'X') {
                                KinkyDungeonMapSet(X, Y, '3');
                                DialogueCreateEnemy(X, Y, "MummyCursed");
                            }
                        }
                    }
                }
            }
            return false;
        },
        options: {
            "Leave": {
                playertext: "Leave", response: "Default",
                exitDialogue: true,
            },
        }
    },
