function KDValidateEscapeGrace(value) {
    if (KDWantsToEscape(value)) {
        let entity = KDGetGlobalEntity(value.id);
        let bondageAmount = Math.min(entity?.boundLevel || 0, KDGetExpectedBondageAmountTotal(value.id, entity));
        let enemy = KinkyDungeonGetEnemyByName(value.type);
        if (enemy && bondageAmount < enemy.maxhp * KDNPCStruggleThreshMultType(enemy)) {
            value.escapegrace = true;
        }
        else
            value.escapegrace = undefined;
    }
    else
        value.escapegrace = undefined;
    return value.escapegrace;
}
function KDSortCollection() {
    KDValidateAllFacilities();
    if (!KDGameData.Collection) {
        KDGameData.Collection = {};
    }
    for (let value of Object.values(KDGameData.Collection)) {
        KDValidateEscapeGrace(value);
    }
    KDGameData.CollectionGuests = 0;
    KDGameData.CollectionSorted = Object.values(KDGameData.Collection).sort((a, b) => {
        let apri = KDEnemyTypeRank(KinkyDungeonGetEnemyByName(a.type));
        let bpri = KDEnemyTypeRank(KinkyDungeonGetEnemyByName(b.type));
        if (KDNPCUnavailable(a.id, a.status))
            apri -= 100;
        if (KDNPCUnavailable(b.id, b.status))
            bpri -= 100;
        if (a.escaped)
            apri -= 20;
        else if (a.escapegrace)
            apri -= 10;
        if (b.escaped)
            bpri -= 20;
        else if (b.escapegrace)
            bpri -= 10;
        if (a.status)
            apri += 1000;
        if (b.status)
            bpri += 1000;
        return bpri - apri;
    });
    for (let a of KDGameData.CollectionSorted) {
        if (a.status == "Servant")
            KDGameData.CollectionGuests++;
    }
}
function KDGenEnemyName(enemy) {
    if (enemy?.Enemy?.nonHumanoid)
        return TextGet("Name" + enemy.Enemy.name);
    let faction = KDGetFaction(enemy) || KDGetFactionOriginal(enemy);
    let nameList = KDFactionProperties[faction]?.nameList ? KDFactionProperties[faction].nameList[Math.floor(Math.random() * KDFactionProperties[faction].nameList.length)] : faction;
    if (enemy.Enemy?.nameList)
        nameList = enemy.Enemy?.nameList;
    if (KDNameList[nameList])
        return KDNameList[nameList][Math.floor(KDNameList[nameList].length * KDRandom())];
    else
        return KDNameList.default[Math.floor(KDNameList.default.length * KDRandom())];
}
function KDGetEnemyName(enemy) {
    return KDGenEnemyName(enemy);
}
