function KDDrawNPCBars(value, x, y, width) {
    let enemy = KDGetGlobalEntity(value.id);
    if (!enemy)
        return 0;
    KDEaseBars(enemy, KDDrawDelta || 0);
    let oldEnemy = enemy.Enemy;
    KDUnPackEnemy(enemy);
    let defaultSpeed = KDIsImprisoned(enemy) || !KinkyDungeonFindID(enemy.id);
    let tooltip = "";
    let tooltipcolor = KDBaseWhite;
    let tooltipAmt = 0;
    let II = 0;
    let height = 12;
    let spacing = height + 2;
    let yy = 0;
    let maxBars = KDNPCStruggleThreshMult(enemy);
    let bindAmpMod = 1;
    if (enemy.boundLevel != undefined && enemy.boundLevel > 0) {
        let visualbond = bindAmpMod * enemy.visual_boundlevel;
        let bindingBars = maxBars;
        let SM = KDGetEnemyStruggleMod(enemy, true, defaultSpeed, false);
        let futureBound = KDPredictStruggle(enemy, SM, 1);
        yy += Math.min(maxBars, bindingBars) * spacing - 10;
        for (let i = 0; i < bindingBars && i < maxBars; i++) {
            if (i > 0)
                II++;
            let mod = visualbond - bindAmpMod * futureBound.boundLevel;
            KinkyDungeonBarTo(kdcanvas, x, y + yy - spacing * II, width, height, Math.min(1, (visualbond - i * enemy.Enemy.maxhp) / enemy.Enemy.maxhp) * 100, KDBaseWhite, "#222222");
            KinkyDungeonBarTo(kdcanvas, 1 + x, y + yy - spacing * II, width, height, Math.min(1, (visualbond - mod - i * enemy.Enemy.maxhp) / enemy.Enemy.maxhp) * 100, "#444444", "none");
        }
        II -= Math.max(0, Math.min(bindingBars - 1, maxBars - 1));
        let bb = 0;
        let bcolor = "#ffae70";
        let bondage = [];
        if (futureBound.specialBoundLevel) {
            for (let b of Object.entries(futureBound.specialBoundLevel)) {
                bondage.push({ name: b[0], amount: b[1] * bindAmpMod, level: 0, pri: KDSpecialBondage[b[0]].priority });
            }
            bondage = bondage.sort((a, b) => {
                return b.pri - a.pri;
            });
        }
        else {
            bondage.push({ name: "Normal", amount: 0, level: futureBound.boundLevel, pri: 0 });
        }
        for (let b of bondage) {
            if (!b.level) {
                b.level = bb + b.amount;
                bb = b.level;
            }
        }
        for (let i = 0; i < bindingBars && i < maxBars; i++) {
            if (i > 0)
                II++;
            let bars = false;
            for (let bi = bondage.length - 1; bi >= 0; bi--) {
                let b = bondage[bi];
                if (b.level > i * enemy.Enemy.maxhp) {
                    bcolor = KDSpecialBondage[b.name] ? KDSpecialBondage[b.name].color : "#ffae70";
                    if (MouseIn(x, y + yy - spacing * II, width, height)) {
                        tooltip = "KDBindType_" + b.name;
                        tooltipcolor = bcolor;
                        tooltipAmt = b.level;
                    }
                    KinkyDungeonBarTo(kdcanvas, x, y + yy - spacing * II, width, height, Math.min(1, (Math.max(0, b.level - i * enemy.Enemy.maxhp)) / enemy.Enemy.maxhp) * 100, bcolor, "none", undefined, undefined, bars ? [0.25, 0.5, 0.75] : undefined, bars ? "#85522c" : undefined, bars ? "#85522c" : undefined, 57.5 + b.pri * 0.01);
                    bars = true;
                }
            }
        }
        enemy.Enemy = oldEnemy;
        if (tooltip) {
            DrawTextFitKD(TextGet(tooltip) + ` (${Math.round(10 * tooltipAmt)})`, MouseX, MouseY - 25, 250, tooltipcolor, KDBaseBlack);
        }
        return bindingBars;
    }
    enemy.Enemy = oldEnemy;
    return 0;
}
function KDCanPromote(value) {
    return KDGetModifiedOpinionID(value.id) > 0 || value.Opinion > 0;
}
function KDPromote(value) {
    value.status = "Servant";
    if (KDIsNPCPersistent(value.id)) {
        KDGetPersistentNPC(value.id).collect = true;
        if (KDGetPersistentNPC(value.id).entity)
            delete KDGetPersistentNPC(value.id).entity.hostile;
        KDUpdatePersistentNPC(value.id);
    }
    delete value.Facility;
}
function KDIsInSummit() {
    return KDGameData.RoomType == "Summit";
}
function KDTickAutorelease() {
    if (KDGameData.AutoRelease?.Escaped)
        for (let value of Object.values(KDGameData.Collection)) {
            if (value.escaped) {
                KDReleaseNPC(value.id, KDPlayer().id);
                KinkyDungeonSendTextMessage(10, TextGet("KDAutoReleased_Escaped")
                    .replace("NME", value.name), KDBaseWhite, 4);
            }
        }
}
function KDDoCollect(entity) {
    if (KDGameData.AutoRelease?.NonNotable) {
        let notable = KDIsNPCPersistent(entity.id);
        if (!notable) {
            if (KDEnemyRank(entity) >= 4)
                return true;
            if (entity.Enemy?.tags?.special)
                return true;
        }
        return notable;
    }
    return true;
}
function KDDefectIfPossible(entity, defectTo = "Player") {
    let op = KDGetModifiedOpinionID(entity.id);
    if (op > 0 && !entity.hostile && entity.faction != "Player" && entity.faction != defectTo) {
        entity.faction = defectTo;
        return true;
    }
    return false;
}
function KDTickCollectionWanderCollectionEntry(value) {
    if (value?.Facility && KDCollectionWanderTypes[value.Facility]) {
        if (KDGetGlobalEntity(value.id) && KDGetGlobalEntity(value.id).FacilityAction != value.Facility) {
            KDChangeEntityFacilityAction(KDGetGlobalEntity(value.id), value.Facility);
        }
        if (KDGameData.RoomType == KDCollectionWanderTypes[value.Facility].spawnRoom
            && KDGameData.RoomType == KDCollectionWanderTypes[value.Facility].spawnRoom) {
            let spawnFunction = KDCollectionWanderTypes[value.Facility].spawnCondition;
            if (spawnFunction) {
                let entity = KinkyDungeonFindID(value.id);
                if (!entity) {
                    if (spawnFunction(value, entity))
                        value.spawned = true;
                    else
                        value.spawned = false;
                }
                else if (entity.FacilityAction)
                    value.spawned = true;
                else
                    value.spawned = false;
            }
        }
        else if (KDIsNPCPersistent(value.id)
            && (KDGetPersistentNPC(value.id)?.room == KDCollectionWanderTypes[value.Facility].spawnRoom)
            && KDGameData.RoomType != KDCollectionWanderTypes[value.Facility].spawnRoom) {
            let spawnFunction = KDCollectionWanderTypes[value.Facility].spawnConditionRemote;
            if (spawnFunction) {
                if (spawnFunction(value))
                    value.spawned = true;
                else
                    value.spawned = false;
            }
        }
    }
    else if (value.spawned) {
        if (KDGetGlobalEntity(value.id) && KDGetGlobalEntity(value.id).FacilityAction != value.Facility) {
            KDChangeEntityFacilityAction(KDGetGlobalEntity(value.id), value.Facility);
        }
    }
}
function KDTickCollectionWanderEntity(entity, delta) {
    let value = KDGameData.Collection[entity.id + ""];
    if (!value)
        return;
    if (entity.FacilityAction && KDCollectionWanderTypes[entity.FacilityAction]?.maintain) {
        KDCollectionWanderTypes[entity.FacilityAction]
            .maintain(value, entity, delta);
    }
}
function KDChangeEntityFacilityAction(entity, action) {
    let value = KDGameData.Collection[entity.id + ""];
    if (!value)
        return;
    if (entity.FacilityAction && KDCollectionWanderTypes[entity.FacilityAction]?.onChangeFacility) {
        entity.FacilityAction = KDCollectionWanderTypes[entity.FacilityAction]
            .onChangeFacility(value, entity, entity.FacilityAction, action);
    }
    else if (entity.FacilityAction == undefined)
        entity.FacilityAction = "Return";
}
function KDSetServantSpawnTemplate(e) {
    if (e) {
        e.allied = 9999;
        e.hostile = 0;
        e.boundLevel = 0;
        e.faction = "Player";
        KDNPCRefreshBondage(e.id, 0, true);
        KinkyDungeonSetEnemyFlag(e, "NoFollow", -1);
        e.hp = e.Enemy.maxhp;
        e.hostile = undefined;
        e.rage = undefined;
    }
}
function KDSetPrisonerSpawnTemplate(e) {
    if (e) {
        e.boundLevel = 0;
        KDNPCRefreshBondage(e.id, 0, true);
        e.hp = e.Enemy.maxhp;
    }
}
