function KDBaseRecycleOutputs() {
    return {
        Latex: 0,
        Metal: 0,
        Rune: 0,
        Leather: 0,
        Rope: 0,
    };
}
function KDGetRecyclerRate(Servants) {
    let output = {};
    let mult = 0.4 * KDGetManagementEfficiency() ** 2;
    for (let id of Servants) {
        let servant = KDGetServantEnemy(KDGameData.Collection["" + id]);
        if (servant) {
            mult += 0.8 + KDEnemyTypeRank(servant);
        }
    }
    for (let resource of Object.keys(RecyclerResources)) {
        let resourceInput = KDGameData.FacilitiesData["RecyclerInput_" + resource];
        let resourceRate = Math.min(resourceInput, mult * RecyclerResources[resource].Rate);
        output[resource] = Math.ceil(resourceRate);
    }
    return output;
}
function KDRecycleItem(item, count = 0, container) {
    let outputs = KDBaseRecycleOutputs();
    let type = KDRestraint(item);
    let variant = KinkyDungeonRestraintVariants[item.inventoryVariant || item.name];
    let res = KDRecyclerResources(type, 1, variant ? (item.inventoryVariant || item.name) : undefined);
    for (let entry of Object.entries(res)) {
        outputs[entry[0]] = (count || 1) * entry[1];
    }
    if (count > 0) {
        for (let i = 0; i < count; i++) {
            if (KinkyDungeonInventoryGetSafe(item.inventoryVariant || item.name, container)) {
                let inv = KinkyDungeonInventoryGetSafe(item.inventoryVariant || item.name, container);
                if (inv.quantity > 1) {
                    inv.quantity -= 1;
                }
                else {
                    KinkyDungeonInventoryRemoveSafe(inv, container);
                }
            }
        }
    }
    return outputs;
}
function KDChangeRecyclerInput(amount, mult = 1) {
    for (let entry of Object.entries(amount)) {
        KDGameData.FacilitiesData["RecyclerInput_" + entry[0]] = Math.max(0, KDGameData.FacilitiesData["RecyclerInput_" + entry[0]] + entry[1] * mult);
    }
}
function KDChangeRecyclerResources(amount, mult = 1) {
    for (let entry of Object.entries(amount)) {
        KDGameData.FacilitiesData["Recycler_" + entry[0]] = Math.max(0, KDGameData.FacilitiesData["Recycler_" + entry[0]] + entry[1] * mult);
    }
}
function KDHasRecyclerResources(amount, mult = 1) {
    for (let entry of Object.entries(amount)) {
        if (entry[1] > 0 && KDGameData.FacilitiesData["Recycler_" + entry[0]] < entry[1] * mult)
            return false;
    }
    return true;
}
function KDHasRecyclerInput(amount) {
    for (let entry of Object.entries(amount)) {
        if (entry[1] > 0 && KDGameData.FacilitiesData["RecyclerInput_" + entry[0]] < entry[1])
            return false;
    }
    return true;
}
function KDRecycleString(item, quantity, container) {
    let temp = "";
    let outputs = KDRecycleItem(item, 0, container);
    for (let output of Object.entries(outputs)) {
        if (output[1] > 0) {
            let str = Math.round(quantity * output[1]) + TextGet("KDRecycleOutput_" + output[0]);
            if (temp.length > 0)
                temp = temp + "";
            temp = temp + str;
        }
    }
    return temp;
}
