function KDDrawRecyclerBlueprints(cats, x, y, width) {
    let XX = 0;
    let YY = 0;
    let colCounter = 0;
    let index = 0;
    let selectedcat = null;
    if (KDSelectedRecyclerCategory == "Null" && cats[0])
        KDSelectedRecyclerCategory = cats[0].name;
    let iin = index;
    let condition = () => {
        return KDMapData.RoomType == "Summit" || KDMapData.RoomType == "PerkRoom";
    };
    for (let cat of cats) {
        let selected = cat.name == KDSelectedRecyclerCategory;
        if (selected)
            selectedcat = cat;
        let hotkey = "";
        if (cats[index + 1]?.name == KDSelectedRecyclerCategory) {
            hotkey = KinkyDungeonKey[1];
        }
        else if (cats[index - 1]?.name == KDSelectedRecyclerCategory) {
            hotkey = KinkyDungeonKey[3];
        }
        if (KDSelectedRecyclerCategory == cat.name)
            iin = index;
        DrawButtonKDExScroll("rec_cat_list" + cat.name, (amount) => {
            if (amount < 0) {
                if (cats[iin - 1]) {
                    KDSelectedRecyclerCategory = cats[iin - 1].name;
                }
            }
            else {
                if (cats[iin + 1]) {
                    KDSelectedRecyclerCategory = cats[iin + 1].name;
                }
            }
        }, () => {
            if (KDSelectedRecyclerCategory != cat.name && cat.items[0]) {
                KDSelectedRecyclerCategory = cat.name;
                KDSelectedRecyclerItem = cat.items[0].name;
            }
            else if (KDSelectedRecyclerCategory == cat.name)
                KDSelectedRecyclerCategory = "";
            return true;
        }, condition(), x + XX + 32, y + YY, 72, 72, "", KDBaseWhite, KinkyDungeonRootDirectory + "UI/Recycler/" + cat.name + ".png", undefined, false, !selected, KDButtonColor, undefined, true, {
            scaleImage: true,
            centered: true,
            hotkey: hotkey ? KDHotkeyToText(hotkey) : undefined,
            hotkeyPress: hotkey,
        });
        colCounter++;
        if (colCounter >= KDRecyclerCatsPerRow) {
            colCounter = 0;
            XX = 0;
            YY += KDRecyclerCatSpacing;
        }
        else {
            XX += KDRecyclerCatSpacing;
        }
        index++;
    }
    YY = 0;
    colCounter = 0;
    let secondXX = KDRecyclerCatSpacing * (KDRecyclerCatsPerRow + 0.5);
    let thirdXX = secondXX + KDRecyclerCatSpacing * (KDRecyclerItemsPerRow + 0.5);
    XX = secondXX;
    let selectedItem = null;
    if (selectedcat) {
        index = 0;
        let items = selectedcat.items;
        let ii = index;
        for (let item of items) {
            if (item.prereq && !item.prereq())
                continue;
            let img = (item.type == Restraint || item.type == LooseRestraint) ?
                KDGetRestraintPreviewImage(KDRestraint({ name: item.item }))
                : KinkyDungeonRootDirectory + "Items/" + item.item + ".png";
            let grp = (item.type == Restraint || item.type == LooseRestraint) ?
                KDGetGroupPreviewImage(KDRestraint({ name: item.item }).Group)
                : "";
            let selected = item.name == KDSelectedRecyclerItem;
            if (selected)
                selectedItem = item;
            let hotkey = "";
            if (items[index + 1]?.name == KDSelectedRecyclerItem) {
                hotkey = KinkyDungeonKey[6];
            }
            else if (items[index - 1]?.name == KDSelectedRecyclerItem) {
                hotkey = KinkyDungeonKey[7];
            }
            let inventoryItem = KinkyDungeonInventoryGetSafe(item.name);
            if (inventoryItem)
                DrawTextFitKD("" + (inventoryItem.quantity || 1), x + XX + 32, y + YY + 60, 72, KDBaseWhite, KDTextGray0, 18, "left", 160);
            if (KDSelectedRecyclerItem == item.name)
                ii = index;
            DrawButtonKDExScroll("rec_item_list" + item.name, (amount) => {
                if (amount < 0) {
                    if (items[ii - 1]) {
                        KDSelectedRecyclerItem = items[ii - 1].name;
                    }
                }
                else {
                    if (items[ii + 1]) {
                        KDSelectedRecyclerItem = items[ii + 1].name;
                    }
                }
            }, () => {
                if (KDSelectedRecyclerItem != item.name)
                    KDSelectedRecyclerItem = item.name;
                else
                    KDSelectedRecyclerItem = "";
                return true;
            }, condition(), x + XX + 32, y + YY, 72, 72, "", KDBaseWhite, img, undefined, false, !selected, KDButtonColor, undefined, true, {
                scaleImage: true,
                centered: true,
                hotkey: hotkey ? KDHotkeyToText(hotkey) : undefined,
                hotkeyPress: hotkey,
            });
            if (grp) {
                KDDraw(kdcanvas, kdpixisprites, "rec_item_list_grp" + item.name, grp, x + XX + 32, y + YY, 72, 72);
            }
            colCounter++;
            if (colCounter >= KDRecyclerItemsPerRow) {
                colCounter = 0;
                XX = secondXX;
                YY += KDRecyclerCatSpacing;
            }
            else {
                XX += KDRecyclerCatSpacing;
            }
            index++;
        }
    }
    YY = 0;
    XX = thirdXX;
    if (selectedItem) {
        let img = (selectedItem.type == Restraint || selectedItem.type == LooseRestraint) ?
            KDGetRestraintPreviewImage(KDRestraint({ name: selectedItem.item }))
            : KinkyDungeonRootDirectory + "Items/" + selectedItem.item + ".png";
        let grp = (selectedItem.type == Restraint || selectedItem.type == LooseRestraint) ?
            KDGetGroupPreviewImage(KDRestraint({ name: selectedItem.item }).Group)
            : "";
        let hotkey = KinkyDungeonKeyEnter[0];
        let canAfford = KDHasRecyclerResources(KDMapToRecycleOutputs(selectedItem.recyclecost));
        let inventoryItem = KinkyDungeonInventoryGetSafe(selectedItem.name);
        DrawTextFitKD(TextGet("KDOwned").replace("AMNT", "" + (inventoryItem ? (inventoryItem.quantity || 1) : 0)), x + XX + 32 + 100, y + YY + 180, 200, KDBaseWhite, KDTextGray0, 18, "center", 160);
        DrawButtonKDEx("rec_item_build" + selectedItem.name, () => {
            KDSendInput("recycleBuild", {
                selectedItem: selectedItem,
            });
            return true;
        }, condition(), x + XX + 32, y + YY, 200, 200, "", KDBaseWhite, img, undefined, false, !canAfford, KDButtonColor, undefined, true, {
            scaleImage: true,
            centered: true,
            hotkey: hotkey ? KDHotkeyToText(hotkey) : undefined,
            hotkeyPress: hotkey,
        });
        let resCenter = x + XX + 32 + 100;
        let res = Object.entries(selectedItem.recyclecost);
        for (let i = 0; i < res.length; i++) {
            let xxx = resCenter - res.length / 2 * 52 + 52 * i;
            let resource = res[i][0];
            KDDraw(kdcanvas, kdpixisprites, "fac_item_res_" + resource, KinkyDungeonRootDirectory + "UI/Resource/" + resource + ".png", xxx, y + YY + 212, 36, 36);
            DrawTextFitKD(Math.ceil(res[i][1]) + "", xxx + 3, y + YY + 212 + 18, 80, KDBaseWhite, KDTextGray0, 18, "right");
        }
        DrawTextFitKD(KDGetItemNameString(selectedItem.item) + (selectedItem.count ? " x" + selectedItem.count : ""), x + XX + 32 + 100, y + YY + 272, 200, KDBaseWhite, KDTextGray0, 24, "center");
        let item = KDItemNoRestraint({ name: selectedItem.name });
        let restraint = KDRestraint({ name: selectedItem.name });
        if (restraint) {
            let pp = (restraint.displayPower != undefined ? restraint.displayPower : restraint.power);
            pp /= 5;
            DrawTextFitKD(TextGet("KinkyDungeonRestraintLevel")
                .replace("RestraintLevel", "" + Math.max(1, restraint.displayPower != undefined ? restraint.displayPower : restraint.power))
                .replace("Rarity", TextGet("KinkyDungeonRarity" + Math.max(0, Math.min(Math.floor(pp), 10)))), x + XX + 32 + 100, y + YY + 300, 200, KDBaseWhite, KDTextGray0, 18, "center");
        }
        else if (item)
            DrawTextFitKD(TextGet("KinkyDungeonRestraintLevel")
                .replace("RestraintLevel", "" + Math.max(1, item.rarity))
                .replace("Rarity", TextGet("KinkyDungeonRarity" + Math.max(0, Math.min(Math.floor(item.rarity), 10)))), x + XX + 32 + 100, y + YY + 300, 200, KDBaseWhite, KDTextGray0, 18, "center");
    }
}
function KDListRecyclerCats() {
    let list = [];
    for (let cat of Object.values(KDRecyclerCategories)) {
        if (cat.prereq()) {
            list.push(cat);
        }
    }
    return list;
}
function KDMapToRecycleOutputs(amount) {
    let outputs = KDBaseRecycleOutputs();
    for (let entry of Object.entries(amount)) {
        outputs[entry[0]] = entry[1];
    }
    return outputs;
}
function KDRecyclerResources(restraint, mult = 1.4, variant) {
    mult *= 1 + Math.max(0, restraint.power * 0.1);
    let res = {};
    if (variant) {
        res.Rune = (res.Rune || 0) + Math.ceil(RecyclerResources.Rune.Yield * mult);
    }
    if (restraint.recycleresource) {
        for (let resource of Object.entries(restraint.recycleresource)) {
            res[resource[0]] = (res[resource[0]] || 0) + Math.ceil(resource[1]);
        }
    }
    else {
        for (let shrine of restraint.shrine) {
            if (RecyclerResources[shrine]) {
                res[shrine] = (res[shrine] || 0) + Math.ceil(RecyclerResources[shrine].Yield * mult);
            }
        }
    }
    return res;
}
function KDAutoGenRestraintBlueprint(name, category, applyvariant, mult = 1.25, forceResourceCost, bonusResource, count = 1) {
    let res = forceResourceCost || {};
    let restraint = KDRestraint({ name: name });
    if (!forceResourceCost) {
        res = KDRecyclerResources(restraint, mult, applyvariant);
    }
    if (mult != 1) {
        for (let r of Object.entries(res)) {
            res[r[0]] = Math.round(mult * r[1]);
        }
    }
    if (bonusResource) {
        for (let r of Object.entries(bonusResource)) {
            res[r[0]] = Math.round((res[r[0]] || 0) + r[1]);
        }
    }
    return {
        name: restraint.name,
        item: restraint.name,
        type: Restraint,
        applyvariant: applyvariant,
        recyclecategory: category,
        recyclecost: res,
        count: count,
        prereq: () => { return true; },
    };
}
function KDRecycleResourceString(allowZero = false, prefix = "Recycler_", noLabel = false) {
    let str = "";
    for (let restype of Object.keys(RecyclerResources)) {
        let amount = KDGameData.FacilitiesData[prefix + restype];
        if (amount != undefined && (allowZero || amount)) {
            if (str)
                str = str + ' ';
            str = str + `(${TextGet("KDRecycleResource_" + restype)}: ${Math.round(amount)})`;
        }
    }
    if (!noLabel)
        str = TextGet("RecycleResStrIntro" + prefix) + str;
    return str;
}
