function InitFacilities() {
    if (!KDGameData.FacilitiesData) {
        KDGameData.FacilitiesData = JSON.parse(JSON.stringify(FacilitiesDataBase));
    }
    else {
        let data = KDGameData.FacilitiesData;
        for (let entry of Object.entries(FacilitiesDataBase)) {
            if (data[entry[0]] == undefined)
                data[entry[0]] = JSON.parse(JSON.stringify(entry[1]));
        }
    }
}
let FacilityValidationTags = ["Servants", "Prisoners", "Guests"];
function KDValidateAllFacilities() {
    for (let facility of Object.keys(KDFacilityTypes)) {
        for (let tag of FacilityValidationTags) {
            let servants = KDGameData.FacilitiesData[tag + "_" + facility];
            if (servants)
                for (let servant of servants) {
                    if (!KDValidateServant(KDGameData.Collection[servant + ""], facility, tag)) {
                        servants.splice(servants.indexOf(servant), 1);
                        if (KDGameData.Collection[servant + ""])
                            delete KDGameData.Collection[servant + ""].Facility;
                    }
                }
        }
    }
    KDGetContainer("WardenChest", undefined, undefined, true, KDWardenChestFilters);
    KDGetContainer("PlayerChest", undefined, undefined, true, KDPlayerChestFilters);
}
function KDUpdateFacilities(delta) {
    KDValidateAllFacilities();
    let listUpdate = Object.entries(KDFacilityTypes).filter((entry) => {
        return entry[1].prereq();
    });
    for (let fac of listUpdate) {
        fac[1].update(delta);
    }
    KDSortCollection();
}
function KinkyDungeonDrawFacilities(xOffset = -125) {
    let x = 1225 + xOffset;
    if (!KinkyDungeonFlags.get("1stSummit")) {
        DrawTextFitKD(TextGet("KDFacilitiesLocked"), x, 300, 1050, KDBaseWhite, KDTextGray0, 24);
    }
    else {
        KDDrawFacilitiesList(xOffset);
    }
    KDDrawInventoryTabs(xOffset);
}
function KDValidateServant(value, facility, type) {
    type = KDFacilityCollectionDataTypeMap[type] || "";
    if (!value)
        return false;
    if (value.status != type)
        return false;
    if (value.escaped)
        return false;
    if (KDIsInPartyID(value.id))
        return false;
    if (KDNPCUnavailable(value.id, value.status))
        return false;
    return true;
}
function KDDrawFacilitiesList(xOffset) {
    let padding = 100;
    let YY = 170;
    let XX = 550 + 125 + xOffset;
    let width = 1050;
    let listRender = Object.entries(KDFacilityTypes).filter((entry) => {
        return entry[1].prereq();
    });
    if (FacilitiesIndex >= listRender.length - 1) {
        FacilitiesIndex = listRender.length - 1;
    }
    let YYQuik = 50;
    let XXQuik = 415;
    let quikSize = 72;
    let quikSpacing = 80;
    let quikCols = 1;
    let quikCurrentCol = 0;
    if (listRender.length * quikSpacing > 900) {
        quikSpacing = 40;
        quikCols = 2;
        quikSize = 36;
    }
    for (let facility of listRender) {
        DrawButtonKDEx("quikFal" + facility[0], () => {
            FacilitiesIndex = listRender.findIndex((entry) => {
                return entry[0] == facility[0];
            });
            return true;
        }, true, XXQuik + quikCurrentCol * quikSpacing, YYQuik, quikSize, quikSize, "", KDBaseWhite, KinkyDungeonRootDirectory + "UI/Facility/" + facility[0] + ".png", undefined, false, false, undefined, undefined, undefined, {
            centered: true,
            zIndex: 110,
        });
        if (facility[1].locked && facility[1].locked())
            KDDraw(kdcanvas, kdpixisprites, "facicon" + facility[0], KinkyDungeonRootDirectory + "Locks/White.png", XXQuik - (quikSize - 56) / 2 + quikCurrentCol * quikSpacing, YYQuik - (quikSize - 56) / 2, 56, 56);
        if (facility[1].ping)
            facility[1].ping(XXQuik, YYQuik, quikCurrentCol, quikSpacing, quikSize);
        if (quikCurrentCol + 1 < quikCols) {
            quikCurrentCol += 1;
        }
        else {
            quikCurrentCol = 0;
            YYQuik += quikSpacing;
        }
    }
    let II = 0;
    let broken = false;
    let rendered = 0;
    for (let facility of listRender) {
        if (II++ < FacilitiesIndex) {
            continue;
        }
        let dist = facility[1].draw(XX, YY, width);
        if (YY + dist > 980) {
            broken = true;
            break;
        }
        FillRectKD(kdcanvas, kdpixisprites, "facrec" + facility[0], {
            Left: XX,
            Top: YY,
            Width: width,
            Height: dist,
            Color: KDBaseBlack,
            LineWidth: 1,
            zIndex: -18,
            alpha: 0.3
        });
        DrawRectKD(kdcanvas, kdpixisprites, "facrec2" + facility[0], {
            Left: XX,
            Top: YY,
            Width: width,
            Height: dist,
            Color: KDBaseBlack,
            LineWidth: 1,
            zIndex: -18,
            alpha: 0.9
        });
        KDDraw(kdcanvas, kdpixisprites, "facicon" + facility[0], KinkyDungeonRootDirectory + "UI/Facility/" + facility[0] + ".png", XX + 1, YY - 76, 72, 72);
        DrawTextFitKD(TextGet("KDFacility_" + facility[0]), XX + 80, YY - 40, width - 160, KDBaseWhite, KDTextGray0, 32, "left");
        let yyy = 0;
        for (let str of TextGet("KDFacilityDesc_" + facility[0]).split('|'))
            DrawTextFitKD(str, XX + 25, YY + 16 + 22 * (yyy++), width - 50, KDBaseWhite, KDTextGray0, 18, "left");
        YY += dist + padding;
        rendered++;
    }
    if (FacilitiesIndex > 0 || broken) {
        DrawButtonKDEx("facUp", (b) => {
            FacilitiesIndex -= 1;
            return true;
        }, FacilitiesIndex > 0, 1650, 110, 150, 40, "", KDBaseWhite, KinkyDungeonRootDirectory + "Up.png", undefined, undefined, !(FacilitiesIndex > 0), KDButtonColor, undefined, undefined, {
            centered: true,
            hotkey: KDHotkeyToText(KinkyDungeonKey[0]),
            hotkeyPress: KinkyDungeonKey[0],
        });
        DrawButtonKDEx("facDown", (b) => {
            FacilitiesIndex += 1;
            return true;
        }, broken, 1650, 850, 150, 40, "", KDBaseWhite, KinkyDungeonRootDirectory + "Down.png", undefined, undefined, !broken, KDButtonColor, undefined, undefined, {
            centered: true,
            hotkey: KDHotkeyToText(KinkyDungeonKey[2]),
            hotkeyPress: KinkyDungeonKey[2],
        });
    }
    if (FacilitiesIndex > 0 || broken) {
        KDDraw(kdcanvas, kdpixisprites, "facScrollBar", KinkyDungeonRootDirectory + "UI/Checked.png", 1695, 175 + 590 * (FacilitiesIndex / Math.max(1, listRender.length - rendered)), 60, 60);
    }
}
function KDGetServantEnemy(servant) {
    if (servant && servant.status == "Servant") {
        return servant.Enemy || KinkyDungeonGetEnemyByName(servant.type);
    }
    return null;
}
let KDFacilityCollectionCallback = null;
function KDDrawServantPrisonerList(facility, x, y, width, spacing = 110, setCallback) {
    let yy = 0;
    let fac = KDFacilityTypes[facility];
    if (fac) {
        let ms = fac.maxServants();
        let mp = fac.maxPrisoners();
        let w = 72;
        if (ms > 0) {
            DrawTextFitKD(TextGet("KDServants") + ": ", x + width / 2 - (spacing * (ms - 1) + w) / 2 - 5, y + yy + 36, 500, KDBaseWhite, KDTextGray0, 24, "right");
            let servants = KDGameData.FacilitiesData["Servants_" + facility];
            for (let i = 0; i < ms; i++) {
                let servant = servants[i];
                DrawButtonKDEx(facility + "serv" + i, (b) => {
                    KDCurrentFacilityTarget = facility;
                    KDCurrentFacilityCollectionType = ["Servants", "Prisoners"];
                    KinkyDungeonDrawState = "Collection";
                    if (KDNPCChar.get(servant))
                        KDRefreshCharacter.set(KDNPCChar.get(servant), true);
                    KDCollectionTab = "";
                    KDCollectionSelected = servant;
                    KDResetCollectionUI();
                    KDFacilityCollectionCallback = setCallback;
                    return true;
                }, true, x + width / 2 - (spacing * (ms - 1) + w) / 2 + i * spacing, y + yy, w, w, "", KDBaseWhite, KDCollectionImage(servant), undefined, undefined, !servant, KDButtonColor, undefined, undefined, {
                    centered: true,
                });
            }
            yy += 100;
        }
        if (mp > 0) {
            DrawTextFitKD(TextGet("KDPrisoners") + ": ", x + width / 2 - (spacing * (mp - 1) + w) / 2 - 5, y + yy + 36, 500, KDBaseWhite, KDTextGray0, 24, "right");
            let prisoners = KDGameData.FacilitiesData["Prisoners_" + facility];
            for (let i = 0; i < mp; i++) {
                let prisoner = prisoners[i];
                DrawButtonKDEx(facility + "pris" + i, (b) => {
                    KDCurrentFacilityTarget = facility;
                    KDCurrentFacilityCollectionType = ["Servants", "Prisoners"];
                    KinkyDungeonDrawState = "Collection";
                    if (KDNPCChar.get(prisoner))
                        KDRefreshCharacter.set(KDNPCChar.get(prisoner), true);
                    KDCollectionTab = "";
                    KDCollectionSelected = prisoner;
                    KDResetCollectionUI();
                    KDFacilityCollectionCallback = setCallback;
                    return true;
                }, true, x + width / 2 - (spacing * (mp - 1) + w) / 2 + i * spacing, y + yy, w, w, "", KDBaseWhite, KDCollectionImage(prisoner), undefined, undefined, !prisoner, KDButtonColor, undefined, undefined, {
                    centered: true,
                });
                if (KDGameData.Collection["" + prisoner]?.escapegrace) {
                    KDDraw(kdcanvas, kdpixisprites, facility + "pris" + i + "escgrc", KinkyDungeonRootDirectory + "UI/escapegrace.png", x + width / 2 - (spacing * (mp - 1) + w) / 2 + i * spacing + w / 2, y + yy + w / 2, w / 2, w / 2, undefined, {
                        zIndex: 110,
                    });
                }
            }
            yy += 110;
        }
    }
    return yy;
}
