function KDLoadModJSON(json) {
    let ret = {
        modname: "",
        moddesc: "",
        author: "",
        modbuild: "",
        gamemajor: 5,
        gameminor: 3,
        gamepatch_min: -1,
        gamepatch_max: -1,
        priority: 0,
        fileorder: [],
    };
    try {
        if (json.length < 100000) {
            Object.assign(ret, JSON.parse(json));
        }
    }
    catch (e) {
        console.log(e.toString());
    }
    return ret;
}
async function KDGetModsLoad(execute) {
    try {
        let API = window.kdAPI;
        if (API) {
            KDOffline = true;
            let modFiles = await API.getMods();
            for (let mod of modFiles) {
                if (mod.file) {
                    const blob = new Blob([mod.file], { type: 'application/octet-stream' });
                    const fileObject = new File([blob], mod.base, { type: 'application/octet-stream' });
                    if (fileObject) {
                        KDMods[mod.base] = fileObject;
                    }
                }
            }
        }
    }
    catch (err) {
    }
    await KDUpdateModInfo();
    if (execute) {
        KDExecuteMods();
    }
}
function KDDrawMods() {
    if (!KDGetMods && (KDToggles.AutoLoadMods || KDToggles.AutoLoadMods == undefined)) {
        KDGetMods = true;
        KDGetModsLoad(false);
    }
    let count = 0;
    let keys = KDModLoadOrder.map((ent) => { return ent.name; });
    for (let i = KDModIndex; i < keys.length && count < KDModCount; i++) {
        let color = "#222222";
        let info = "KDNoModJSON";
        let name = keys[i];
        let ver = "0";
        let num1 = "" + VersionMajor;
        let num2 = "" + VersionMajor;
        if (KDModInfo[keys[i]]) {
            color = KDBaseWhite;
            info = "";
            try {
                name = KDModInfo[keys[i]].modname || name;
                if (KDModInfo[keys[i]].gamemajor >= 0 && VersionMajor != KDModInfo[keys[i]].gamemajor) {
                    color = KDBaseRed;
                    info = "KDModOutdated2";
                    num2 = "" + KDModInfo[keys[i]].gamemajor;
                }
                else if (KDModInfo[keys[i]].gameminor >= 0 && VersionMinor != KDModInfo[keys[i]].gameminor) {
                    color = KDBaseOrange;
                    info = "KDModOutdated3";
                    num1 = "" + VersionMinor;
                    num2 = "" + KDModInfo[keys[i]].gameminor;
                }
                else if (KDModInfo[keys[i]].gamepatch_min >= 0 && VersionPatch < KDModInfo[keys[i]].gamepatch_min) {
                    color = KDBaseYellow;
                    info = "KDModOutdated";
                    num1 = "" + VersionPatch;
                    num2 = `>${KDModInfo[keys[i]].gamepatch_min}`;
                }
                else if (KDModInfo[keys[i]].gamepatch_max >= 0 && VersionPatch > KDModInfo[keys[i]].gamepatch_max) {
                    color = KDBaseYellow;
                    info = "KDModOutdated";
                    num1 = "" + VersionPatch;
                    num2 = `<${KDModInfo[keys[i]].gamepatch_max}`;
                }
                ver = KDModInfo[keys[i]].modbuild;
            }
            catch (e) {
                console.log(e.toString());
                color = "#ff00ff";
                info = "KDModMiscError";
            }
        }
        DrawTextKD(name + (info ? ` (${TextGet(info)
            .replace("${Num1}", num1)
            .replace("${Num2}", num2)})` : (TextGet("KDModVer") + ver)), 975, 370 + KDModSpacing * count, color, KDTextGray2);
        if (!KDExecuted)
            DrawButtonKDEx("moddelete_" + i, (bdata) => {
                delete KDMods[keys[i]];
                delete KDModInfo[keys[i]];
                KDUpdateModInfo();
                return true;
            }, true, 1625, 350 + KDModSpacing * count, 200, 45, TextGet("KinkyDungeonDeleteMod"), KDBaseWhite, "");
        count++;
    }
}
function getFileInput(callback, ...callbackArgs) {
    let input = document.createElement('input');
    input.type = 'file';
    input.multiple = true;
    input.onchange = _this => {
        let files = Array.from(input.files);
        if (callback) {
            callback(files, ...callbackArgs);
        }
        else
            KDLoadMod(files);
    };
    input.click();
}
async function KDLoadMod(files) {
    console.log(files);
    for (let f of files) {
        if (f && f.name) {
            KDMods[f.name] = f;
            KDLoadModJSON[f.name] = null;
        }
    }
    await KDUpdateModInfo();
}
let KDExecuted = false;
let KDLoading = false;
async function KDExecuteModsAndStart() {
    await KDExecuteMods();
    if (!KDToggles.OverrideOutfit)
        KinkyDungeonConfigAppearance = false;
    KinkyDungeonStartNewGame(true);
}
async function KDUpdateModInfo() {
    while (KDLoading) {
        await sleep(100);
    }
    KDLoading = false;
    let errored = false;
    let modsProcessed = 0;
    let modFiles = [];
    try {
        KDModLoadOrder = [];
        for (let mod of Object.entries(KDMods)) {
            let file = mod[1];
            let entries = await model.getEntries(file, {});
            let priority = 0;
            let foundInfo = false;
            if (entries && entries.length) {
                for (let entry of entries) {
                    let filename = entry.filename.split('/').pop();
                    if (filename == 'mod.json') {
                        foundInfo = true;
                        const controller = new AbortController();
                        const signal = controller.signal;
                        const blobURL = await model.getURL(entry, {
                            password: undefined,
                            onprogress: (index, max) => {
                                console.log(`Loading progress: ${index},${max}`);
                            },
                            signal
                        });
                        let blob = await fetch(blobURL).then(r => r.blob());
                        let reader = new FileReader();
                        let file = new File([blob], entry.filename);
                        await new Promise((resolve, reject) => {
                            reader.onload = function (event) {
                                console.log("LOADING MOD INFO " + file.name);
                                if (typeof event.target.result === "string") {
                                    let res = event.target.result;
                                    let json = KDLoadModJSON(res);
                                    if (json) {
                                        KDModInfo[mod[0]] = json;
                                        if (json.priority) {
                                            priority = json.priority;
                                        }
                                        modFiles.push({ mod: mod[1], name: mod[0], priority: priority, fileorder: json.fileorder });
                                        KDModLoadOrder = modFiles.sort((a, b) => {
                                            return (b.priority || 0) - (a.priority || 0);
                                        }).map((ent) => { return { mod: ent.mod, name: ent.name, fileorder: ent.fileorder }; });
                                        modsProcessed += 1;
                                        resolve(true);
                                    }
                                    else
                                        resolve(false);
                                }
                            };
                            reader.readAsText(file);
                        });
                    }
                }
            }
            if (!foundInfo) {
                modFiles.push({ mod: mod[1], name: mod[0], priority: priority, fileorder: [] });
                modsProcessed += 1;
            }
        }
        console.log(modFiles);
    }
    catch (e) {
        modsProcessed = Object.entries(KDMods).length;
        console.log(e.toString());
        errored = true;
        KDModLoadOrder = Object.entries(KDMods).map((ent) => { return { mod: ent[1], name: ent[0], fileorder: [] }; });
    }
    while (modsProcessed < Object.entries(KDMods).length) {
        await sleep(100);
    }
    if (!errored)
        KDModLoadOrder = modFiles.sort((a, b) => {
            return (b.priority || 0) - (a.priority || 0);
        }).map((ent) => { return { mod: ent.mod, name: ent.name, fileorder: ent.fileorder }; });
    KDLoading = false;
}
let KDModLoadOrder = [];
async function KDExecuteMods() {
    if (KDExecuted || Object.keys(KDModLoadOrder).length == 0)
        return;
    KDExecuted = true;
    KDAwaitingModLoad = true;
    KDAllModFiles = [];
    await KDUpdateModInfo();
    if (KDOffline) {
        let mods = [];
        for (let file of KDModLoadOrder.map((ent) => { return ent.mod; })) {
            console.log(file.path);
            mods.push(file.path);
        }
        localStorage.setItem("KDMods", JSON.stringify(mods));
        await KDUpdateModInfo();
    }
    for (let file of KDModLoadOrder.map((ent) => { return ent.mod; })) {
        let entries = await model.getEntries(file, {});
        if (entries && entries.length) {
            entries.forEach((entry, entryIndex) => {
                KDAllModFiles.push(entry);
            });
            KDModFileCount++;
        }
    }
    let processMod = async (mod) => {
        console.log(`Loading ${mod.name}`);
        let fileloader = Promise.resolve(null);
        let entries = await model.getEntries(mod.mod, {});
        for (let entry of entries) {
            if ((!mod.fileorder.includes(entry.filename)) && (!entry.filename.endsWith('.csv'))) {
                mod.fileorder.push(entry.filename);
            }
        }
        for (let entry of entries) {
            if (entry.filename.endsWith(`EN.csv`)) {
                mod.fileorder.push(entry.filename);
            }
        }
        if (TranslationLanguage !== '') {
            for (let entry of entries) {
                if (entry.filename.endsWith(`${TranslationLanguage}.csv`)) {
                    mod.fileorder.push(entry.filename);
                }
            }
        }
        console.log(mod.fileorder);
        try {
            await mod.fileorder.reduce(async (promiseChain, currFile) => {
                await promiseChain;
                return processFile(currFile, entries);
            }, Promise.resolve(null));
        }
        catch (err) {
            console.log(err);
        }
    };
    let processFile = async (file, entries) => {
        console.log("Loading " + file);
        try {
            const entry = entries.find((ent) => ent.filename == file);
            const controller = new AbortController();
            const signal = controller.signal;
            const blobURL = await model.getURL(entry, {
                password: undefined,
                onprogress: (index, max) => {
                    console.log(`Loading progress: ${index},${max}`);
                },
                signal
            });
            console.log(blobURL);
            let blob = await fetch(blobURL).then(r => r.blob());
            console.log(blob);
            if (file.startsWith('.')) {
            }
            else if (file.endsWith('EN.csv') || ((file.endsWith(`${TranslationLanguage}.csv`)) && (TranslationLanguage !== ''))) {
                try {
                    let reader = new FileReader();
                    let file = new File([blob], entry.filename);
                    reader.onload = function (event) {
                        console.log(`READING TRANSLATIONS FILE ${file}`);
                        if (typeof event.target.result === "string") {
                            let res = event.target.result;
                            KDLoadTranslations(res);
                        }
                    };
                    reader.readAsText(file);
                }
                catch (err) {
                    console.log(`Error while loading ${file} - ${err}`);
                }
            }
            else if (file.endsWith('.js') || file.endsWith('.ks')) {
                try {
                    let reader = new FileReader();
                    let readfile = new File([blob], entry.filename);
                    await new Promise((resolve, reject) => {
                        reader.onload = async function (event) {
                            console.log("EXECUTING MOD FILE " + file);
                            if (typeof event.target.result === "string") {
                                let res = event.target.result;
                                if (KDToggles.ModCompat) {
                                    for (let compat of Object.entries(KDModCompat)) {
                                        console.log(`Replacing ${compat[0]} with ${compat[1]}`);
                                        const escapedKey = compat[0].replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                                        res = res.replace(new RegExp(escapedKey, 'g'), compat[1]);
                                    }
                                }
                                let evaluated = await eval(res);
                                resolve(evaluated);
                            }
                        };
                        reader.readAsText(readfile);
                    });
                }
                catch (err) {
                    console.log(`Error while loading ${file} - ${err}`);
                }
            }
            else {
                KDModFiles[KinkyDungeonRootDirectory + file] = URL.createObjectURL(blob);
                KDModFiles[KinkyDungeonRootDirectory + "" + file] = KDModFiles[KinkyDungeonRootDirectory + file];
                if (file?.startsWith("Data/")
                    || file?.startsWith("DisplacementMaps/")
                    || file?.startsWith("Models/")
                    || file?.startsWith("ModelsBack/")
                    || file?.startsWith("TextureAtlas/")
                    || file?.startsWith("Music/")) {
                    KDModFiles[file] = URL.createObjectURL(blob);
                    KDModFiles[PIXI.utils.path.toAbsolute(file)] = URL.createObjectURL(blob);
                }
            }
        }
        catch (err) {
            console.log(err);
        }
    };
    try {
        await KDModLoadOrder.reduce(async (promiseChain, currMod) => {
            await promiseChain;
            return processMod(currMod);
        }, Promise.resolve(null));
        console.log("Finished Loading Mods");
        KDLoadModSettings();
    }
    catch (err) {
        console.log(err);
    }
    for (let [k, v] of Object.entries(KDModFiles)) {
        let ext = PIXI.utils.path.extname(k);
        KDModFiles[PIXI.utils.path.toAbsolute(k)] = v;
        PIXI.Assets.resolver.add(k, {
            src: v,
            format: ext,
        });
        PIXI.Assets.resolver.add(PIXI.utils.path.toAbsolute(k), {
            src: v,
            format: ext,
        });
    }
    if (KDAllModFiles.length > 0)
        KDModsLoaded = true;
    KDLoadPerks();
    KinkyDungeonRefreshRestraintsCache();
    KinkyDungeonRefreshEnemiesCache();
    KDAwaitingModLoad = false;
    KinkyDungeonSendEvent("afterLoadMods", {});
    KDRefreshCharacter.set(KinkyDungeonPlayer, true);
    KinkyDungeonCheckClothesLoss = true;
    KinkyDungeonDressPlayer();
}
