        KDCurrentCharacterPalettes = KDGetPalettes(C, true, true, C == KinkyDungeonPlayer ? KDDefaultWardrobePalettes : ((KinkyDungeonPlayer.metadata?.customColors) ? Object.assign(Object.assign({}, KDDefaultWardrobePalettes), KinkyDungeonPlayer.metadata.customColors) : KDDefaultWardrobePalettes));
        let YY = 55;
        let size = 48;
