function KDAbbreviate(str, context) {
    let abbreviations = KDGetAbbreviations(context);
    for (let i = 0; i < 1; i++) {
        let found = false;
        for (let entry of Object.entries(abbreviations)) {
            if (str.includes(entry[0])) {
                found = true;
                str = str.replace(entry[0], entry[1]);
            }
        }
        if (!found)
            break;
    }
    return str;
}
